import React, { useState } from 'react';
import axios from 'axios';
import { CheckCircle, AlertCircle, Clock, Copy, Download } from 'lucide-react';

const API_BASE = 'http://localhost:5000'; // directly pointing to working backend

export default function App() {
  const [step, setStep] = useState('landing');
  const [testCode, setTestCode] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [testInboxes, setTestInboxes] = useState([]);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);
  const [pollCount, setPollCount] = useState(0);

  // Create Test
  const startTest = async () => {
    if (!userEmail || !/^\S+@\S+\.\S+$/.test(userEmail)) {
      setError('Please enter a valid email');
      return;
    }
    setError('');
    setLoading(true);

    try {
      const res = await axios.post(`${API_BASE}/api/tests/create`, { userEmail });
      setTestCode(res.data.testCode);
      setTestInboxes(res.data.testInboxes);
      setStep('setup');
    } catch (err) {
      setError(err.response?.data?.message || 'Error creating test');
    } finally {
      setLoading(false);
    }
  };

  // Check Results with polling
  const checkResults = async () => {
    setLoading(true);
    setPollCount(0);

    const poll = async () => {
      try {
        const res = await axios.post(`${API_BASE}/api/tests/check`, { testCode });
        if (res.data.status === 'complete' || res.data.results.length > 0) {
          setResults(res.data);
          setStep('results');
          setLoading(false);
        } else if (pollCount < 12) {
          setPollCount(pollCount + 1);
          setTimeout(poll, 5000); // poll every 5 seconds
        } else {
          setError('Timeout: Email not found after 1 minute');
          setLoading(false);
        }
      } catch (err) {
        setError(err.response?.data?.message || 'Error checking results');
        setLoading(false);
      }
    };

    poll();
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const resetTest = () => {
    setStep('landing');
    setTestCode('');
    setUserEmail('');
    setResults(null);
    setError('');
  };

  // ---------- UI ----------

  // Landing
  if (step === 'landing') {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 bg-gray-50">
        <div className="bg-white p-8 rounded-lg shadow-md max-w-md w-full">
          <h1 className="text-3xl font-bold mb-4">Inbox Checker</h1>
          <input
            type="email"
            placeholder="your@email.com"
            value={userEmail}
            onChange={(e) => setUserEmail(e.target.value)}
            className="w-full mb-4 px-4 py-2 border rounded"
          />
          {error && <p className="text-red-600 mb-2">{error}</p>}
          <button
            onClick={startTest}
            disabled={loading}
            className="w-full bg-blue-600 text-white py-2 rounded"
          >
            {loading ? 'Creating Test...' : 'Start Test'}
          </button>
        </div>
      </div>
    );
  }

  // Setup
  if (step === 'setup') {
    return (
      <div className="min-h-screen p-4 flex flex-col items-center justify-center bg-gray-50">
        <div className="bg-white p-6 rounded shadow-md max-w-md w-full">
          <h2 className="text-xl font-bold mb-4">Send Test Email</h2>
          <p className="mb-4">
            Send an email to this inbox with the code: <strong>{testCode}</strong>
          </p>
          {testInboxes.map((inbox) => (
            <div key={inbox} className="mb-2 flex justify-between items-center bg-gray-100 p-2 rounded">
              <span>{inbox}</span>
              <button onClick={() => copyToClipboard(inbox)} className="text-blue-600">
                {copied ? 'Copied!' : 'Copy'}
              </button>
            </div>
          ))}
          <button
            onClick={checkResults}
            disabled={loading}
            className="mt-4 w-full bg-green-600 text-white py-2 rounded"
          >
            {loading ? 'Checking...' : 'Check Results'}
          </button>
        </div>
      </div>
    );
  }

  // Results
  if (step === 'results' && results) {
    const score = results.deliveryScore;
    return (
      <div className="min-h-screen p-4 flex flex-col items-center justify-center bg-gray-50">
        <div className="bg-white p-6 rounded shadow-md max-w-md w-full">
          <h2 className="text-xl font-bold mb-4">Deliverability Report</h2>
          <p className="mb-4">Inbox Delivery Rate: <strong>{score}%</strong></p>
          {results.results.map((r) => (
            <div key={r.inbox} className={`p-2 mb-2 rounded ${r.received ? 'bg-green-100' : 'bg-red-100'}`}>
              <div className="flex justify-between">
                <span>{r.inbox}</span>
                {r.received ? <CheckCircle className="text-green-600" /> : <AlertCircle className="text-red-600" />}
              </div>
              <p className="text-sm">{r.received ? `Folder: ${r.folder}` : 'Email not found'}</p>
            </div>
          ))}
          <button onClick={resetTest} className="mt-4 w-full bg-gray-300 py-2 rounded">New Test</button>
        </div>
      </div>
    );
  }

  // Loading
  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <Clock className="animate-spin" size={40} />
      <p>Loading...</p>
    </div>
  );
}
